import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  channelLinksTransactionsChannelSchema,
  type ChannelLinksTransactionsChannel,
} from "./channel-links-transactions-channel.js";
import {
  statusLinksTransactionsStatusSchema,
  type StatusLinksTransactionsStatus,
} from "./status-links-transactions-status.js";
import {
  typeLinksTransactionsTypeSchema,
  type TypeLinksTransactionsType,
} from "./type-links-transactions-type.js";

export type TransactionList = {
  /** A unique identifier generated by Global Payments to identify the transaction. */
  id?: string;
  /**
   * Merchant's time indicating when the transaction was first created. Value is in ISO-8601 format.
   */
  timeCreated?: string;
  /**
   * Indicates where a transaction is in its lifecycle. * INITIATED - A Transaction has been
   * successfully initiated. An update on its status is expected via a separate asynchronous
   * notification to a webhook. * PENDING - A Transaction has been sent to the payment method
   * provider and are waiting for a result. * PREAUTHORIZED - A Transaction has been approved but a
   * capture request is required to commence the movement of funds. * CAPTURED - A Transaction has
   * been successfully authorized and captured. The funding process will commence once the
   * transaction remains in this status. * REVERSED - A Transaction that had a status of PENDING,
   * PREAUTHORIZED or CAPTURED has subsequently been reversed which voids/cancels a transaction
   * before it is funded. * DECLINED - A Transaction where the payment method provider declined the
   * transfer of funds between the payer and the merchant. * FUNDED - A Transaction where the funds
   * have transferred between payer and merchant as expected. * REJECTED - A Transaction where the
   * funds were expected to transfer between payer and merchant but the transfer was rejected during
   * the funding process. This rarely happens but when it does it is usually addressed by Global
   * Payments operations.
   */
  status?: StatusLinksTransactionsStatus;
  /**
   * Describes whether the transaction is a SALE, that moves funds from Payer to Merchant, or a
   * REFUND where funds move from Merchant to Payer. * SALE - indicates the movement, or the attempt
   * to move, funds from payer to a merchant. * REFUND - indicates the movement, or the attempt to
   * move, funds from merchant to the payer.
   */
  type?: TypeLinksTransactionsType;
  /**
   * Describes whether the transaction was processed in a face to face(CP) scenario or a Customer
   * Not Present (CNP) scenario. * CP - A Customer Present transaction is when the payer and the
   * merchant are in direct face to face contact when exchanging payment method information to
   * fulfill a transaction. e.g. in a store and paying at the counter that is attended by a clerk. *
   * CNP - A Customer NOT Present transaction is when the payer and the merchant are not together
   * when exchanging payment method information to fulfill a transaction. e.g. a transaction
   * executed from a merchant's website or over the phone
   */
  channel?: ChannelLinksTransactionsChannel;
  /**
   * The amount to transfer between Payer and Merchant for a SALE or a REFUND. It is always
   * represented in the lowest denomination of the related currency.
   */
  amount?: string;
  /** The currency of the amount in ISO-4217(alpha-3) */
  currency?: string;
  /** Merchant defined field to reference the transaction. */
  reference?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const transactionListProperties: s.Shape<TransactionList> = {
  id: s.optional(s.string()),
  timeCreated: s.optional(s.string()),
  status: s.optional(s.lazy(() => statusLinksTransactionsStatusSchema)),
  type: s.optional(s.lazy(() => typeLinksTransactionsTypeSchema)),
  channel: s.optional(s.lazy(() => channelLinksTransactionsChannelSchema)),
  amount: s.optional(s.string()),
  currency: s.optional(s.string()),
  reference: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
  },
};

export const transactionListInternalSchema: Schema<TransactionList> = s.object<TransactionList>(
  transactionListProperties,
  { additionalProperties: s.json() },
);

export const transactionListSchema: Schema<TransactionList> = s.lazySchema(() =>
  s.object<TransactionList>(
    {
      ...transactionListProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(100))),
      currency: s.optional(s.string().check(s.minLength(3), s.maxLength(3))),
      reference: s.optional(s.string().check(s.minLength(8), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
